import java.util.Scanner;

class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + "发出了一声叫");
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：汪！");
    }
}

class Fish extends Animal {
    Fish(String name) {
        super(name);
    }

    @Override
    void speak() {
        System.out.println(name + "：咕噜咕噜");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Dog d = new Dog("{dog}");
        Fish f = new Fish("{fishName}");
        Animal a = new Animal("{animalName}");
        for (int i = 0; i < n; i++) {
            d.speak();
        }
        f.speak();
        a.speak();
    }
}
